// The loader returns one summary item, or an error if it failed (the node continues on error)
const src = $('Each source').first().json;
const result = $input.first().json;
if (result.error || result.status === undefined) {
  const message = result.error?.message ?? result.error ?? 'Loader returned no result';
  return [{ json: { ...src, failed: true, status: 'failed', error: String(message) } }];
}
return [{ json: { ...src, ...result, failed: false } }];

const r = $input.first().json;
return [{ json: {
  run_id: r.run_id, agent: 'collection', action: 'load', source: r.source,
  target_table: `raw.${r.table}`, status: 'failed', rows_read: null, rows_written: null,
  duration_ms: null, reason: `Loading ${r.label} failed: ${r.error}`,
  details: JSON.stringify({ type: r.type, error: r.error }),
} }];

