// Build the prompt from the profile and sample only. Whole tables are never sent to the LLM.
const src = $('Each loaded source').first().json;
const profile = $('Profile columns').all().map(i => i.json);
const sample = $('Sample rows').all().map(i => {
  const row = { ...i.json };
  delete row._run_id; delete row._loaded_at;
  for (const k of Object.keys(row)) {
    if (typeof row[k] === 'string' && row[k].length > 200) row[k] = row[k].slice(0, 200) + '…';
  }
  return row;
});
const prompt = [
  `Source: ${src.source}`,
  `Arrived as: ${src.type} (${src.label})`,
  `Raw table: raw.${src.table}`,
  `Rows loaded: ${src.rows_written}`,
  '',
  'Column profile (JSON):',
  JSON.stringify(profile),
  '',
  'Random sample of 20 rows (JSON):',
  JSON.stringify(sample),
].join('\n');
return [{ json: { prompt, source: src.source, table: src.table, run_id: src.run_id } }];

