const meta = $('Build contract prompt').first().json;
return [{ json: {
  run_id: meta.run_id,
  source: meta.source,
  raw_table: `raw.${meta.table}`,
  contract: JSON.stringify($input.first().json.output),
} }];

const checks = $input.all().map(i => i.json);
const loaded = $('Loaded sources').all().map(i => ({ source: i.json.source, type: i.json.type, rows: i.json.rows_written }));
const prompt = [
  'Sources loaded in this run (JSON):',
  JSON.stringify(loaded),
  '',
  'Cross-source check results (JSON):',
  JSON.stringify(checks),
].join('\n');
return [{ json: { prompt, run_id: $('Loaded sources').first().json.run_id } }];

