const meta = $('Build mismatch prompt').first().json;
return [{ json: {
  run_id: meta.run_id,
  source: '_cross_source',
  raw_table: null,
  contract: JSON.stringify($input.first().json.output),
} }];

const loaded = $('Loaded sources').all().map(i => i.json);
const all = $('Sources').all().map(i => i.json);
const report = $('Mismatch agent').first().json.output;
const flagged = (report.mismatches ?? []).length;
return [{ json: {
  run_id: all[0].run_id,
  agent: 'collection',
  action: 'run_complete',
  source: null,
  target_table: null,
  status: loaded.length === all.length ? 'success' : 'warning',
  rows_read: loaded.reduce((n, s) => n + (s.rows_read ?? 0), 0),
  rows_written: loaded.reduce((n, s) => n + (s.rows_written ?? 0), 0),
  duration_ms: null,
  reason: `${loaded.length} of ${all.length} sources loaded; ${flagged} cross-source mismatches flagged`,
  details: JSON.stringify({ loaded: loaded.map(s => s.source), failed: all.filter(s => !loaded.some(l => l.source === s.source)).map(s => s.source) }),
} }];
